/**
 * Function that returns the hyperbolic sine of a number
 *
 * @author Martin Veillette (Berea College)
 */
import '../../../globals.js';
import dot from '../dot.js';
export function sinh(value) {
    return (Math.exp(value) - Math.exp(-value)) / 2;
}
dot.register('sinh', sinh);
